ss=np.sum((dv_dt-dv_dt.mean())**2)
def polf(vars_,deg):
    cols=[np.ones_like(t)]
    for d in range(1,deg+1):
        for comb in itertools.combinations_with_replacement(range(len(vars_)),d):
            p=np.ones_like(t)
            for z in comb: p=p*vars_[z]
            cols.append(p)
    return np.column_stack(cols)
